package com.nvidia.rtxremix.minecraft.sky;

/**
 * Exposes the positions generated by Minecraft's canonical star-field builder.
 */
public interface WorldRendererStarAccess {

    /**
     * Returns a copy of the generated position-only star vertices.
     *
     * @return packed XYZ positions in Minecraft's star-field object space
     */
    float[] rtxremix$copyStarVertices();
}
